class Solution {
    public int longestConsecutive(int[] nums) {
        if (nums.length == 0) return 0;

        Set<Integer> numSet = new HashSet<>();
        for (int num : nums) {
            numSet.add(num);
        }

        int maxLength = 0;

        for (int num : numSet) {
            // Only start counting if num is the start of a sequence
            if (!numSet.contains(num - 1)) {
                int currentNum = num;
                int currentLength = 1;

                while (numSet.contains(currentNum + 1)) {
                    currentNum++;
                    currentLength++;
                }

                maxLength = Math.max(maxLength, currentLength);
            }
        }

        return maxLength;
    }
}

class Solution {
    public int longestConsecutive(int[] nums) {
        if (nums.length == 0) return 0;

        Arrays.sort(nums);

        int maxLength = 1;
        int currentLength = 1;

        for (int i = 1; i < nums.length; i++) {
            // Skip duplicates
            if (nums[i] == nums[i - 1]) continue;

            if (nums[i] == nums[i - 1] + 1) {
                currentLength++;
            } else {
                maxLength = Math.max(maxLength, currentLength);
                currentLength = 1;
            }
        }

        return Math.max(maxLength, currentLength);
    }
}

class Solution {
    private int[] parent;
    private int[] rank;
    private int maxSize;

    public int longestConsecutive(int[] nums) {
        if (nums.length == 0) return 0;

        Map<Integer, Integer> numToIdx = new HashMap<>();
        int n = nums.length;
        parent = new int[n];
        rank = new int[n];
        maxSize = 1;

        // Initialize
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 1;
        }

        for (int i = 0; i < n; i++) {
            if (numToIdx.containsKey(nums[i])) continue;
            numToIdx.put(nums[i], i);

            if (numToIdx.containsKey(nums[i] - 1)) {
                union(i, numToIdx.get(nums[i] - 1));
            }
            if (numToIdx.containsKey(nums[i] + 1)) {
                union(i, numToIdx.get(nums[i] + 1));
            }
        }

        return maxSize;
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
                rank[rootY] += rank[rootX];
                maxSize = Math.max(maxSize, rank[rootY]);
            } else {
                parent[rootY] = rootX;
                rank[rootX] += rank[rootY];
                maxSize = Math.max(maxSize, rank[rootX]);
            }
        }
    }
}
